import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017-APR-12 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-APR-12 :: Ceph Performance Weekly","date":"2017-05-16T00:00:00.000Z","updated":"2017-05-17T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","蓝存储","Pull Request"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),p={name:"posts/2017/2017-APR-12_-_-_Ceph_Performance_Weekly.md"};function s(o,l,n,u,g,_){return t(),i("div",null,[...l[0]||(l[0]=[r("<p>本次Ceph性能会议于2023年X月X日举行，主要讨论了Ceph系统的性能优化和Pull Request的相关议题。以下是会议的主要内容：</p><p><strong>一、Ceph Pull Requests讨论</strong></p><ol><li><p><strong>Igor的工作</strong>：</p><ul><li>成功合并了修复小文件性能问题的pull request，提高了系统的鲁棒性。</li><li>提交了参数调整和添加硬盘SSD变体的pull request，需要进一步审查。</li><li>发现蓝存储在NVMe上的性能下降，需进一步分析。</li><li>提交了将blob转换为blob的pull request，需单独测试。</li></ul></li><li><p><strong>Brightest Law的工作</strong>：</p><ul><li>合并了速度表优化和限流模型优化的pull request，用户现在在蓝存储中只有一个限流指标。</li><li>下一个pull request将测试自动调整限流，基于目标延迟进行调整。</li></ul></li><li><p><strong>其他pull requests</strong>：</p><ul><li>一些pull requests正在审查中，包括文件顺序调整和回调合并等。</li></ul></li></ol><p><strong>二、蓝存储性能问题</strong></p><ol><li><p><strong>蓝存储缓存测试失败</strong>：</p><ul><li>需要重新运行测试，检查是否有问题。</li></ul></li><li><p><strong>分离PVC线程</strong>：</p><ul><li>将线程分为两部分可能有助于提高性能。</li></ul></li><li><p><strong>蓝存储文件系统优化</strong>：</p><ul><li>将蓝存储文件系统放置在硬盘中间可以减少臂运动，提高性能。</li></ul></li><li><p><strong>文件系统检查内存使用</strong>：</p><ul><li>需要进一步分析内存使用情况，确保没有未计数的内存使用。</li></ul></li></ol><p><strong>三、其他议题</strong></p><ol><li><p><strong>墙钟分析</strong>：</p><ul><li>讨论了墙钟分析工具的选择，包括gdb、py-cpu-profiler等。</li></ul></li><li><p><strong>libunwind问题</strong>：</p><ul><li>讨论了libunwind在信号处理中的问题。</li></ul></li></ol><p><strong>四、行动计划</strong></p><ol><li><p><strong>Igor</strong>：</p><ul><li>审查和合并参数调整和硬盘SSD变体的pull request。</li><li>分析蓝存储在NVMe上的性能下降问题。</li></ul></li><li><p><strong>Brightest Law</strong>：</p><ul><li>测试自动调整限流的pull request。</li></ul></li><li><p><strong>Mark</strong>：</p><ul><li>重新运行蓝存储缓存测试，检查是否有问题。</li></ul></li><li><p><strong>Nick</strong>：</p><ul><li>分析文件系统检查内存使用情况。</li></ul></li><li><p><strong>所有人员</strong>：</p><ul><li>关注墙钟分析工具的选择和libunwind问题。</li></ul></li></ol><p>本次会议重点关注了Ceph系统中蓝存储的性能优化，以及相关Pull Request的审查和合并。会议还讨论了墙钟分析工具和libunwind问题，并制定了相应的行动计划。</p>",10)])])}const d=e(p,[["render",s]]);export{c as __pageData,d as default};
